mapper.select:
select l.log_id, l.member_id, l.type_code, t.type_name, m.phone, l.currency, l.biz_type, l.biz_id, l.amount,
       l.available_before, l.available_after, l.frozen_before, l.frozen_after,
       l.remark, l.operator, l.create_time
from biz_wallet_log l
left join biz_member m on m.member_id = l.member_id
left join biz_wallet_type t on t.type_code = l.type_code

    and l.member_id = #{memberId}
    and l.type_code = #{typeCode}
    and l.currency = #{currency}
    and l.biz_type = #{bizType}
    and m.phone like concat('%', #{phone}, '%')
    and l.remark like concat('%', #{remark}, '%')
    and l.create_time >= #{params.beginTime}
    and l.create_time < date_add(#{params.endTime}, interval 1 day)

order by l.log_id desc

select l.log_id, l.member_id, l.type_code, t.type_name, m.phone, l.currency, l.biz_type, l.biz_id, l.amount,
       l.available_before, l.available_after, l.frozen_before, l.frozen_after,
       l.remark, l.operator, l.create_time
from biz_wallet_log l
left join biz_member m on m.member_id = l.member_id
left join biz_wallet_type t on t.type_code = l.type_code
where l.member_id = #{memberId}
  and l.available_before <> l.available_after
and l.currency = #{currency}
and l.type_code = #{walletTypeCode}

  and (
    l.biz_type in

      #{item}


      or l.biz_type = 'ADJUST'

  )

order by l.log_id desc

select ifnull(sum(amount), 0)
from biz_wallet_log
where member_id = #{memberId}
  and currency = #{currency}
  and (
    biz_type in ('CHECKIN', 'KYC_REWARD', 'INVITE', 'COMMISSION', 'LEVEL_REWARD')
    or (biz_type = 'ADJUST' and type_code = 'PROMO')
  )
